INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7457555, 1181337, 97225, '<td valign="top">Congrats on tt. Lovely shot. I have had a similar experience with one of those spheres. I put it down on a wooden picnic table and almost immediately got a spiral of smoke and left a little charred spot. I hadn''t yet set it up for shooting, in fact I put it down because it burnt my hand.</td>', 'Congrats on tt. Lovely shot. I have had a similar experience with one of those spheres. I put it down on a wooden picnic table and almost immediately got a spiral of smoke and left a little charred spot. I hadn''t yet set it up for shooting, in fact I put it down because it burnt my hand.', '2016-05-30 19:13:19.000000', NULL, 0),
(7458530, 1181332, 59029, '<td valign="top">Greetings from the Critique Club!<br/> <br/>A good attempt at an interesting challenge entry, especially in your first challenge and in one that can be very technically tricky.  The colours are nice and poppy, you were careful to NOT oversharpen (and trust me, I''ve oversharpened many an entry esp in my early years here).  Your settings are a tiny bit on the slow side for any kind of critter motion shot, a little bit faster would have helped to freeze the blur on that left parrot.  Exposure and composition are ok; I think if there had been some interaction between the parrots, ie fighting over or sharing a piece of food, that this would have scored a bit higher.  Voters here look for relatability.  I personally am a little sad to see the parrots are chained to the cage.<br/> <br/>Watch that the whites don''t get too hard and flat, bleaching them out just makes for a mess that detracts the eye.  Meanwhile you clearly do have an eye, keep entering and requesting critiques!<br/> <br/>Susan</td>', 'Greetings from the Critique Club! A good attempt at an interesting challenge entry, especially in your first challenge and in one that can be very technically tricky.  The colours are nice and poppy, you were careful to NOT oversharpen (and trust me, I''ve oversharpened many an entry esp in my early years here).  Your settings are a tiny bit on the slow side for any kind of critter motion shot, a little bit faster would have helped to freeze the blur on that left parrot.  Exposure and composition are ok; I think if there had been some interaction between the parrots, ie fighting over or sharing a piece of food, that this would have scored a bit higher.  Voters here look for relatability.  I personally am a little sad to see the parrots are chained to the cage. Watch that the whites don''t get too hard and flat, bleaching them out just makes for a mess that detracts the eye.  Meanwhile you clearly do have an eye, keep entering and requesting critiques! Susan', '2016-06-03 22:56:10.000000', NULL, 0),
(7475478, 1181337, 182284, '<td valign="top">I almost caught my deck on fire by putting one on the railing of my deck. What a surprise when I saw the smoke! BTW, awesome shot!<br/><br/><i>Message edited by author 2016-09-23 16:31:47.</i></td>', 'I almost caught my deck on fire by putting one on the railing of my deck. What a surprise when I saw the smoke! BTW, awesome shot!', '2016-09-23 17:30:52.000000', '2016-09-23 17:31:47.000000', 0),
